import {useCurrentUser} from '@github-ui/current-user'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {useMutation} from '@github-ui/react-query'
import {ScopedCommands} from '@github-ui/ui-commands'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {ActionList, ActionMenu, Button, ConfirmationDialog, FormControl, Stack, Textarea} from '@primer/react'
import {useCallback, useEffect, useId, useState} from 'react'

import {useIterationHistory} from '../contexts/IterationHistoryContext'
import {useWorkbenchContext} from '../contexts/WorkbenchContext'
import {isError, useCheckName} from '../hooks/use-check-name'
import {ReadOnlyKey, useReadOnly} from '../hooks/use-read-only'
import {useWorkbench, type UseWorkbenchReturn} from '../hooks/use-workbench'
import type {Iteration} from '../types/workbench-types'
import {NameInput} from './NameInput'
import styles from './SettingsPanel.module.css'

export function SettingsPanel() {
  const workbench = useWorkbench()

  const {previousRefinements} = useIterationHistory()
  const {userAgentModelPreference, setUserAgentModelPreference} = useWorkbenchContext()
  const currentUser = useCurrentUser()

  const readOnly = useReadOnly(ReadOnlyKey.DEFAULT)
  const agentModelLabelId = useId()
  const deleteTitleId = useId()
  const deleteDescriptionId = useId()

  const [isDeleteConfirmationOpen, setIsDeleteConfirmationOpen] = useState(false)

  const {mutate: deleteSpark, isPending} = useMutation({
    mutationFn: async () => {
      await verifiedFetchJSON(`/copilot/spark/workbench/${workbench.id}`, {
        method: 'DELETE',
      })
    },
    onSuccess: () => {
      window.location.href = '/spark'
    },
  })

  return (
    <div className={styles.container}>
      <BasicForm
        name={workbench.name}
        description={workbench.description}
        isFetching={workbench.isFetching}
        previousRefinements={previousRefinements}
        updateWorkbenchSettings={workbench.updateWorkbenchSettings}
      />

      {currentUser?.isStaff && (
        <FormControl>
          <FormControl.Label id={agentModelLabelId} className="mb-1">
            Agent model
          </FormControl.Label>
          <ActionMenu>
            <ActionMenu.Button aria-labelledby={agentModelLabelId} disabled={readOnly}>
              {userAgentModelPreference}
            </ActionMenu.Button>
            <ActionMenu.Overlay width="auto">
              <ActionList selectionVariant="single">
                <ActionList.Item
                  selected={userAgentModelPreference === 'claude-sonnet-4.5'}
                  onSelect={() => setUserAgentModelPreference('claude-sonnet-4.5')}
                >
                  Claude Sonnet 4.5
                </ActionList.Item>
                <ActionList.Item
                  selected={userAgentModelPreference === 'claude-sonnet-4'}
                  onSelect={() => setUserAgentModelPreference('claude-sonnet-4')}
                >
                  Claude Sonnet 4
                </ActionList.Item>
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        </FormControl>
      )}

      <div>
        <div id={deleteTitleId} className={styles.dangerZoneTitle}>
          Delete spark
        </div>
        <p id={deleteDescriptionId} className={styles.subtitle}>
          Once you delete a spark, there is no going back. Please be certain.
        </p>
        <Button
          size="medium"
          variant="danger"
          onClick={() => setIsDeleteConfirmationOpen(true)}
          loading={isPending}
          aria-describedby={`${deleteTitleId} ${deleteDescriptionId}`}
        >
          Delete
        </Button>
        {isDeleteConfirmationOpen && (
          <ConfirmationDialog
            title="Delete spark"
            onClose={gesture => {
              if (gesture === 'confirm') {
                deleteSpark()
              }
              setIsDeleteConfirmationOpen(false)
            }}
            confirmButtonContent="Delete"
            confirmButtonType="danger"
          >
            Are you sure you want to delete this spark? This action can’t be undone.
          </ConfirmationDialog>
        )}
      </div>
    </div>
  )
}

function BasicForm({
  name,
  description,
  isFetching,
  previousRefinements,
  updateWorkbenchSettings,
}: {
  name: string
  description: string
  isFetching: boolean
  previousRefinements: Iteration[]
  updateWorkbenchSettings: UseWorkbenchReturn['updateWorkbenchSettings']
}) {
  const [localName, setLocalName] = useState<string>(name ?? '')
  const [localDescription, setLocalDescription] = useState<string>(description ?? '')
  const descriptionLabelId = useId()

  // Use a stable no-op callback to prevent infinite re-renders.
  const onValidityChange = useCallback(() => {}, [])
  const [result, runCheck] = useCheckName(onValidityChange)

  const [loading, setLoading] = useState(false)
  const [errorMessages, setErrorMessages] = useState<Record<string, string | undefined>>({})

  const readOnly = useReadOnly(ReadOnlyKey.DEFAULT)

  useEffect(() => {
    setLocalName(name)
  }, [name])

  useEffect(() => {
    setLocalDescription(description)
  }, [description])

  const handleSubmit = async (e?: React.FormEvent<HTMLFormElement>) => {
    e?.preventDefault()

    if (!localName) {
      setErrorMessages(errors => ({...errors, name: 'Name is required'}))
      return
    }
    // Button may still be clickable even if it looks disabled so check!
    if (buttonDisabled) {
      return
    }
    const sparkRenameFixEnabled = isFeatureEnabled('spark_fix_rename')
    const friendlyNameToSave = sparkRenameFixEnabled ? result.generatedName ?? localName : result.generatedName
    await updateWorkbenchSettings(localName, localDescription, friendlyNameToSave)
    setLoading(false)
  }

  const handleNameChange = (newName: string) => {
    setLocalName(newName)
    setErrorMessages(errors => ({...errors, name: undefined}))
  }

  const inputDisabled = readOnly || isFetching || previousRefinements.length === 0
  const buttonDisabled =
    readOnly ||
    isFetching ||
    previousRefinements.length === 0 ||
    (localName === name && localDescription === description) ||
    isError(result)

  return (
    <ScopedCommands commands={{'github:submit-form': () => handleSubmit()}}>
      <form onSubmit={handleSubmit}>
        <Stack>
          <NameInput
            sparkName={localName}
            onChange={handleNameChange}
            onValidityChange={onValidityChange}
            result={result}
            runCheck={runCheck}
            disabled={inputDisabled}
          />

          <FormControl disabled={inputDisabled}>
            <FormControl.Label id={descriptionLabelId}>Description</FormControl.Label>
            <Textarea
              block
              rows={6}
              name="description"
              aria-labelledby={descriptionLabelId}
              value={localDescription}
              placeholder="Enter description"
              onChange={e => {
                setLocalDescription(e.target.value)
                setErrorMessages(errors => ({...errors, description: undefined}))
              }}
            />
            <FormControl.Caption>Generated by Spark</FormControl.Caption>
            {errorMessages.description && (
              <FormControl.Validation variant="error">
                <span>{errorMessages.description}</span>
              </FormControl.Validation>
            )}
          </FormControl>
          <div>
            <Button
              type="submit"
              variant="primary"
              inactive={buttonDisabled && !readOnly}
              aria-disabled={buttonDisabled && !readOnly}
              disabled={readOnly}
              loading={loading}
            >
              Save changes
            </Button>
          </div>
        </Stack>
      </form>
    </ScopedCommands>
  )
}

try{ SettingsPanel.displayName ||= 'SettingsPanel' } catch {}
try{ BasicForm.displayName ||= 'BasicForm' } catch {}