import {announce as announceToScreenReader} from '@github-ui/aria-live'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {FormControl, TextInput} from '@primer/react'
import {type ChangeEvent, forwardRef, useEffect, useId, useMemo, useRef} from 'react'

import {type CheckResult, isError} from '../hooks/use-check-name'
import type {WorkbenchRoutePayload} from '../types/workbench-types'

const repoInputDefaultMessageId = 'RepoNameInput-message'
// Delay announcements so screen readers finish reading the updated input value first
export const PUBLISHED_MESSAGE_ANNOUNCEMENT_DELAY_MS = 1000

interface NameInputProps {
  sparkName: string
  disabled?: boolean
  hideBlankCheck?: boolean
  onChange: (newRepoName: string) => void
  onValidityChange: ({valid, invalidReason}: {valid: boolean; invalidReason?: string}) => void
  expandNameInput?: boolean
  result: CheckResult
  runCheck: (newName: {friendlyName: string}) => void
}

export const NameInput = forwardRef((props: NameInputProps, ref: React.ForwardedRef<HTMLInputElement>) => {
  const {sparkName, onChange, onValidityChange, expandNameInput, result, runCheck} = props
  const isInputDisabled = Boolean(props.disabled)
  const labelText = 'Name'
  const inputId = useId()
  const publishedSparkMessageId = useId()
  const {workbench} = useRoutePayload<WorkbenchRoutePayload>()
  const shouldAnnounceNextPublishRef = useRef(false)
  const publishedMessageAnnouncementTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  const publishedSparkName = useMemo(() => {
    if (!workbench?.runtime?.owner) {
      return undefined
    }

    if (result.status === 'reworded' || result.status === 'ok') {
      return `${result.generatedName}--${workbench.runtime.owner.deployLogin}.${workbench.runtime.owner.deploymentDomainBase}`
    }
    return undefined
  }, [workbench?.runtime?.owner, result.generatedName, result.status])

  const duplicateSparkError = useMemo(() => {
    if (result.status !== 'error' || !result.generatedName || !result.errors) {
      return undefined
    }

    const normalized = result.errors.toLowerCase()
    if (!normalized.includes('already used') && !normalized.includes('already exists')) {
      return undefined
    }

    return {sparkName: result.generatedName, errorText: result.errors}
  }, [result.errors, result.generatedName, result.status])

  const shouldShowPublishedMessage = Boolean(publishedSparkName)
  const shouldShowDuplicateMessage = Boolean(duplicateSparkError)

  const handleInputChange = (event: ChangeEvent<HTMLInputElement>) => {
    shouldAnnounceNextPublishRef.current = true
    onChange(event.target.value)
  }

  const activeDescriptionId = useMemo(() => {
    if (!sparkName) {
      return props.hideBlankCheck ? undefined : repoInputDefaultMessageId
    }

    if (shouldShowPublishedMessage) {
      return publishedSparkMessageId
    }

    return repoInputDefaultMessageId
  }, [props.hideBlankCheck, publishedSparkMessageId, shouldShowPublishedMessage, sparkName])

  useEffect(() => {
    let invalidReason = 'none'
    if (!sparkName) {
      invalidReason = 'empty'
    }

    onValidityChange({valid: false, invalidReason})
    runCheck({friendlyName: sparkName})
  }, [onValidityChange, runCheck, sparkName])

  useEffect(() => {
    if (!shouldShowPublishedMessage || !publishedSparkName) {
      if (publishedMessageAnnouncementTimeoutRef.current) {
        clearTimeout(publishedMessageAnnouncementTimeoutRef.current)
        publishedMessageAnnouncementTimeoutRef.current = null
      }
      return
    }

    if (!shouldAnnounceNextPublishRef.current) {
      return
    }

    shouldAnnounceNextPublishRef.current = false

    if (publishedMessageAnnouncementTimeoutRef.current) {
      clearTimeout(publishedMessageAnnouncementTimeoutRef.current)
    }

    publishedMessageAnnouncementTimeoutRef.current = setTimeout(() => {
      announceToScreenReader(getPublishedSparkAnnouncement(publishedSparkName))
      publishedMessageAnnouncementTimeoutRef.current = null
    }, PUBLISHED_MESSAGE_ANNOUNCEMENT_DELAY_MS)
  }, [publishedSparkName, shouldShowPublishedMessage])

  useEffect(() => {
    return () => {
      if (publishedMessageAnnouncementTimeoutRef.current) {
        clearTimeout(publishedMessageAnnouncementTimeoutRef.current)
        publishedMessageAnnouncementTimeoutRef.current = null
      }
    }
  }, [])

  return (
    <FormControl id={inputId} required disabled={isInputDisabled}>
      <FormControl.Label requiredIndicator={false}>{labelText}</FormControl.Label>
      <TextInput
        block
        data-1p-ignore="true"
        ref={ref}
        name="name"
        aria-describedby={activeDescriptionId}
        className={expandNameInput ? 'width-full' : ''}
        value={sparkName}
        placeholder="Enter name"
        onChange={handleInputChange}
        validationStatus={isError(result) ? 'error' : undefined}
      />
      <NameCheckValidation
        result={result}
        sparkName={sparkName}
        hideBlankCheck={props.hideBlankCheck}
        suppressGeneratedNameError={shouldShowDuplicateMessage}
      />
      {shouldShowPublishedMessage && publishedSparkName ? (
        <PublishedSparkMessage id={publishedSparkMessageId} publishedSparkName={publishedSparkName} />
      ) : null}
      {shouldShowDuplicateMessage && duplicateSparkError ? (
        <DuplicateSparkMessage sparkName={duplicateSparkError.sparkName} errorText={duplicateSparkError.errorText} />
      ) : null}
    </FormControl>
  )
})

NameInput.displayName = 'RepoNameInput'

interface NameCheckValidationProps {
  sparkName: string
  hideBlankCheck?: boolean
  result: CheckResult
  suppressGeneratedNameError?: boolean
}

function NameCheckValidation(props: NameCheckValidationProps) {
  const {sparkName, result, suppressGeneratedNameError} = props

  if (!sparkName) {
    return props.hideBlankCheck ? null : (
      <FormControl.Validation id={repoInputDefaultMessageId} variant="error">
        New repository name must not be blank
      </FormControl.Validation>
    )
  }

  switch (result.status) {
    case 'none':
      return (
        // This component is a descendant of `FormControl`
        // eslint-disable-next-line primer-react/direct-slot-children
        <FormControl.Caption id={repoInputDefaultMessageId} aria-live="polite">
          Checking availability…
        </FormControl.Caption>
      )
    case 'not_found':
      return (
        <FormControl.Validation id={repoInputDefaultMessageId} variant="error">
          Not Found
        </FormControl.Validation>
      )
    case 'error':
      return result.generatedName ? (
        suppressGeneratedNameError ? null : (
          <FormControl.Validation id={repoInputDefaultMessageId} variant="error">
            The spark <strong>{result.generatedName}</strong> {result.errors}.
          </FormControl.Validation>
        )
      ) : (
        // An error without repo is not coming from the server, it's likely a fetch error
        <FormControl.Validation id={repoInputDefaultMessageId} variant="error">
          {"Couldn't check availability"}
        </FormControl.Validation>
      )
    case 'reworded':
    case 'ok':
      return null
  }
}

function PublishedSparkMessage({id, publishedSparkName}: {id: string; publishedSparkName: string}) {
  return (
    // eslint-disable-next-line primer-react/direct-slot-children
    <FormControl.Caption>
      {/* Focusable so assistive tech reads the published name announcement on blur */}
      {/* eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex */}
      <span id={id} tabIndex={0} data-testid="published-name-message">
        Your spark will be published as <strong>{publishedSparkName}</strong>.
      </span>
    </FormControl.Caption>
  )
}

const getPublishedSparkAnnouncement = (publishedSparkName: string) =>
  `Your spark will be published as ${publishedSparkName}.`

function DuplicateSparkMessage({sparkName, errorText}: {sparkName: string; errorText: string}) {
  return (
    <FormControl.Validation id={repoInputDefaultMessageId} variant="error">
      {/* Focusable so assistive tech reads the duplicate warning on blur */}
      {/* eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex */}
      <span tabIndex={0} data-testid="spark-name-error-message">
        The spark <strong>{sparkName}</strong> {errorText}.
      </span>
    </FormControl.Validation>
  )
}

try{ NameCheckValidation.displayName ||= 'NameCheckValidation' } catch {}
try{ PublishedSparkMessage.displayName ||= 'PublishedSparkMessage' } catch {}
try{ DuplicateSparkMessage.displayName ||= 'DuplicateSparkMessage' } catch {}